import type { ReactNode } from 'react'
import './marketing.css'

type MarketingSectionProps = {
  eyebrow?: string
  title?: string
  description?: string
  tone?: 'default' | 'raised' | 'quiet'
  children: ReactNode
  id?: string
}

export function MarketingSection({ eyebrow, title, description, tone = 'default', children, id }: MarketingSectionProps) {
  return <section className="marketing-section marketing-surface" data-tone={tone} id={id}>
    <div className="marketing-section-inner">
      {(eyebrow || title || description) && <div className="marketing-section-heading">
        <div>{eyebrow && <p className="marketing-eyebrow">{eyebrow}</p>}{title && <h2>{title}</h2>}</div>
        {description && <p className="marketing-section-description">{description}</p>}
      </div>}
      {children}
    </div>
  </section>
}

.marketing-surface {
  --marketing-max: 1180px;
  color: var(--foreground);
  font-family: var(--font-sans);
}

.marketing-button {
  position: relative;
  display: inline-flex;
  min-height: 46px;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid transparent;
  border-radius: var(--control-radius);
  padding: 0 20px;
  color: var(--primary-foreground);
  background: var(--primary);
  box-shadow: var(--actions-shadow);
  font: var(--label-weight) 14px/1 var(--font-sans);
  text-decoration: none;
  cursor: pointer;
  transition: color var(--motion-duration) var(--motion-easing),
    background-color var(--motion-duration) var(--motion-easing),
    border-color var(--motion-duration) var(--motion-easing),
    transform var(--motion-duration) var(--motion-easing);
}
.marketing-button:hover { background: color-mix(in srgb, var(--primary) 88%, white); }
.marketing-button:active { transform: translateY(var(--actions-pressed-offset)); }
.marketing-button:focus-visible { outline: 3px solid var(--ring); outline-offset: 3px; }
.marketing-button:disabled,.marketing-button[aria-disabled="true"] { opacity: .52; pointer-events: none; }
.marketing-button[data-variant="secondary"] { color: var(--foreground); background: var(--secondary); border-color: var(--border); box-shadow: none; }
.marketing-button[data-variant="secondary"]:hover { background: color-mix(in srgb, var(--secondary) 80%, var(--accent)); }
.marketing-button[data-variant="ghost"] { color: var(--foreground); background: transparent; box-shadow: none; }
.marketing-button[data-variant="ghost"]:hover { background: var(--muted); }
.marketing-button[data-size="lg"] { min-height: 52px; padding-inline: 24px; font-size: 15px; }
.marketing-button[data-size="sm"] { min-height: 40px; padding-inline: 15px; font-size: 13px; }
.marketing-button svg { width: 18px; height: 18px; flex: none; stroke-width: var(--icon-stroke); }
.marketing-button-spinner { width: 16px; height: 16px; border: 2px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: marketing-spin .8s linear infinite; }

.marketing-header { position: relative; z-index: 5; display: flex; width: 100%; align-items: center; justify-content: space-between; gap: 24px; padding: 18px clamp(20px, 4vw, 54px); border-bottom: 1px solid color-mix(in srgb, var(--border) 70%, transparent); background: color-mix(in srgb, var(--background) 86%, transparent); backdrop-filter: blur(18px); }
.marketing-brand { display: inline-flex; align-items: center; gap: 10px; color: var(--foreground); font-family: var(--font-heading); font-size: 18px; font-weight: 700; text-decoration: none; }
.marketing-brand-mark { width: 16px; height: 16px; border-radius: 50%; background: var(--primary); box-shadow: 0 0 0 7px color-mix(in srgb, var(--primary) 15%, transparent); }
.marketing-nav { display: flex; align-items: center; gap: 26px; }
.marketing-nav a { color: var(--muted-foreground); font-size: 14px; text-decoration: none; }
.marketing-nav a:hover,.marketing-nav a:focus-visible { color: var(--foreground); }
.marketing-header-actions { display: flex; align-items: center; gap: 10px; }
.marketing-menu-trigger { display: none; width: 44px; height: 44px; place-items: center; border: 1px solid var(--border); border-radius: var(--control-radius); color: var(--foreground); background: var(--card); }
.marketing-menu-trigger svg { width: 20px; height: 20px; }

.marketing-hero { position: relative; isolation: isolate; display: grid; min-height: 640px; overflow: hidden; grid-template-columns: minmax(0,1.08fr) minmax(320px,.92fr); gap: clamp(38px, 8vw, 100px); align-items: center; padding: clamp(72px, 10vw, 132px) clamp(24px, 6vw, 86px); background: linear-gradient(146deg, var(--card), var(--background) 68%); }
.marketing-hero::before { content:""; position: absolute; z-index: -2; inset: -45% -20% 6% 30%; border: 24px solid color-mix(in srgb, var(--accent) 26%, transparent); border-radius: 48%; transform: rotate(-10deg); box-shadow: 0 0 0 34px color-mix(in srgb,var(--chart-3) 11%,transparent),0 0 0 70px color-mix(in srgb,var(--accent) 7%,transparent); }
.marketing-hero::after { content:""; position:absolute; z-index:-1; width:220px; height:220px; top:8%; right:5%; border-radius:50%; background:radial-gradient(circle,var(--primary) 0 27%,color-mix(in srgb,var(--primary) 58%,white) 28% 42%,color-mix(in srgb,var(--accent) 44%,transparent) 43% 58%,transparent 59%); opacity:.94; }
.marketing-hero-copy { position: relative; z-index: 1; max-width: 720px; }
.marketing-eyebrow { display: inline-flex; align-items: center; gap: 8px; margin: 0 0 18px; color: var(--primary); font-size: 12px; font-weight: 700; letter-spacing: .11em; }
.marketing-eyebrow::before { content:""; width:8px; height:8px; border-radius:50%; background:currentColor; box-shadow:0 0 0 5px color-mix(in srgb,currentColor 14%,transparent); }
.marketing-hero h1 { max-width: 12ch; margin: 0; font-size: clamp(48px, 7vw, 88px); line-height: 1.02; letter-spacing: -.035em; text-wrap: balance; }
.marketing-hero-description { max-width: 38rem; margin: 24px 0 0; color: var(--muted-foreground); font-size: clamp(17px, 2vw, 20px); line-height: 1.75; }
.marketing-hero-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 34px; }
.marketing-hero-visual { position: relative; z-index: 1; align-self: end; }
.marketing-orbit-panel { position: relative; min-height: 330px; overflow: hidden; border: 1px solid color-mix(in srgb,var(--accent) 55%,transparent); border-radius: 36px 36px 120px 36px; padding: 30px; background: color-mix(in srgb,var(--card) 88%,transparent); box-shadow: var(--overlays-shadow); backdrop-filter: blur(14px); }
.marketing-orbit-panel::after { content:""; position:absolute; width:250px; height:250px; right:-80px; bottom:-110px; border:18px solid color-mix(in srgb,var(--accent) 30%,transparent); border-radius:50%; box-shadow:0 0 0 24px color-mix(in srgb,var(--accent) 10%,transparent); }
.marketing-orbit-value { margin-top: 84px; font: 750 clamp(68px,9vw,108px)/.85 var(--font-sans); letter-spacing:-.06em; }
.marketing-orbit-meta { display:flex; justify-content:space-between; gap:16px; margin-top:22px; color:var(--muted-foreground); font-size:13px; }

.marketing-section { padding: clamp(64px, 9vw, 112px) clamp(24px, 6vw, 86px); background: var(--background); }
.marketing-section[data-tone="raised"] { background: var(--card); }
.marketing-section[data-tone="quiet"] { background: var(--sidebar); }
.marketing-section-inner { width: min(100%, var(--marketing-max)); margin-inline: auto; }
.marketing-section-heading { display:grid; grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr); gap: clamp(28px, 8vw, 100px); align-items:end; margin-bottom:48px; }
.marketing-section h2 { max-width: 14ch; margin:0; font-size:clamp(34px,5vw,60px); }
.marketing-section-description { max-width: 42rem; margin:0; color:var(--muted-foreground); font-size:17px; }

.marketing-card-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:16px; }
.marketing-card { position:relative; display:flex; min-width:0; min-height:260px; flex-direction:column; overflow:hidden; border:1px solid var(--border); border-radius:var(--surface-radius); padding:26px; background:var(--card); color:var(--card-foreground); box-shadow:var(--data-display-shadow); }
.marketing-card[data-variant="feature"]:first-child { grid-column:span 2; }
.marketing-card[data-variant="feature"]::after { content:""; position:absolute; width:160px; height:160px; right:-58px; top:-70px; border:14px solid color-mix(in srgb,var(--accent) 22%,transparent); border-radius:50%; }
.marketing-card-label { color:var(--primary); font-size:12px; font-weight:700; letter-spacing:.08em; }
.marketing-card h3 { max-width:18ch; margin:18px 0 12px; font-size:clamp(24px,3vw,36px); }
.marketing-card p { max-width:42ch; margin:0; color:var(--muted-foreground); }
.marketing-card-footer { display:flex; align-items:center; justify-content:space-between; gap:18px; margin-top:auto; padding-top:28px; }
.marketing-card-value { color:var(--primary); font-size:32px; font-weight:750; }

.marketing-form { display:grid; gap:20px; width:min(100%,560px); }
.marketing-field { display:grid; gap:8px; min-width:0; }
.marketing-field-label { font-size:14px; font-weight:var(--label-weight); }
.marketing-field-hint,.marketing-field-error { margin:0; font-size:13px; }
.marketing-field-hint { color:var(--muted-foreground); }
.marketing-field-error { color:var(--destructive); }
.marketing-input,.marketing-select-trigger { width:100%; min-width:0; min-height:48px; border:1px solid var(--input); border-radius:var(--control-radius); padding:0 16px; background:color-mix(in srgb,var(--background) 80%,var(--card)); color:var(--foreground); box-shadow:var(--inputs-shadow); font:14px var(--font-sans); }
.marketing-input::placeholder { color:color-mix(in srgb,var(--muted-foreground) 78%,transparent); }
.marketing-input:hover,.marketing-select-trigger:hover { border-color:var(--border); }
.marketing-input:focus-visible,.marketing-select-trigger:focus-visible { border-color:var(--ring); outline:3px solid color-mix(in srgb,var(--ring) 35%,transparent); outline-offset:2px; }
.marketing-input[aria-invalid="true"],.marketing-select-trigger[aria-invalid="true"] { border-color:var(--destructive); box-shadow:0 0 0 2px color-mix(in srgb,var(--destructive) 18%,transparent); }
.marketing-input:disabled,.marketing-select-trigger:disabled { opacity:.5; cursor:not-allowed; }
.marketing-form-actions { display:flex; flex-wrap:wrap; gap:12px; }
.marketing-form-status { min-height:24px; color:var(--success); font-size:14px; }

.marketing-select-trigger { display:flex; align-items:center; justify-content:space-between; gap:12px; text-align:left; cursor:pointer; }
.marketing-select-trigger[data-popup-open]:not([data-popup-open="false"]) { border-color:var(--ring); }
.marketing-select-trigger-icon { display:inline-flex; width:16px; height:16px; align-items:center; justify-content:center; line-height:0; }
.marketing-select-trigger-icon svg { width:16px; height:16px; stroke-width:var(--icon-stroke); transition:transform var(--motion-duration) var(--motion-easing); }
.marketing-select-trigger[data-popup-open]:not([data-popup-open="false"]) .marketing-select-trigger-icon svg { transform:rotate(180deg); }
.marketing-select-positioner { z-index:100; }
.marketing-select-popup { width:var(--anchor-width); max-width:calc(100vw - 24px); max-height:min(320px,var(--available-height)); overflow:auto; border:1px solid var(--border); border-radius:var(--overlay-radius); padding:7px; background:var(--popover); color:var(--popover-foreground); box-shadow:var(--overlays-shadow); transform-origin:var(--transform-origin); }
.marketing-select-item { position:relative; display:flex; min-height:44px; align-items:center; justify-content:space-between; gap:12px; border-radius:12px; padding:8px 10px; outline:none; cursor:default; }
.marketing-select-item[data-highlighted] { background:var(--accent); color:var(--accent-foreground); }
.marketing-select-item[data-selected]:not([data-highlighted]) { color:var(--primary); }
.marketing-select-item[data-disabled] { opacity:.45; }
.marketing-select-item-indicator { display:grid; width:18px; height:18px; place-items:center; }
.marketing-select-item-indicator svg { width:16px; height:16px; }

.marketing-icon { display:inline-grid; width:44px; height:44px; place-items:center; border:1px solid var(--border); border-radius:14px; color:var(--foreground); background:var(--muted); }
.marketing-icon[data-tone="primary"] { color:var(--primary-foreground); background:var(--primary); border-color:transparent; }
.marketing-icon[data-tone="quiet"] { color:var(--muted-foreground); background:transparent; }
.marketing-icon svg { width:20px; height:20px; stroke-width:var(--icon-stroke); }
.marketing-star-mark { display:inline-block; width:14px; height:14px; border-radius:50%; background:var(--primary); box-shadow:0 0 0 6px color-mix(in srgb,var(--primary) 14%,transparent); }

.marketing-footer { padding:54px clamp(24px,6vw,86px) 28px; border-top:1px solid var(--border); background:var(--sidebar); }
.marketing-footer-inner { display:grid; width:min(100%,var(--marketing-max)); margin:auto; grid-template-columns:1.2fr repeat(3,.6fr); gap:36px; }
.marketing-footer-brand p { max-width:30ch; color:var(--muted-foreground); }
.marketing-footer-group { display:grid; align-content:start; gap:10px; }
.marketing-footer-group h3 { margin:0 0 6px; font:var(--label-weight) 13px var(--font-sans); }
.marketing-footer-group a { color:var(--muted-foreground); font-size:13px; text-decoration:none; }
.marketing-footer-group a:hover { color:var(--foreground); }
.marketing-footer-bottom { display:flex; width:min(100%,var(--marketing-max)); justify-content:space-between; gap:18px; margin:42px auto 0; padding-top:22px; border-top:1px solid var(--sidebar-border); color:var(--muted-foreground); font-size:12px; }

.marketing-preview-stack { display:grid; width:100%; gap:18px; }
.marketing-preview-row { display:flex; flex-wrap:wrap; gap:12px; align-items:center; }

@keyframes marketing-spin { to { transform:rotate(1turn); } }
@media (prefers-reduced-motion:reduce) { .marketing-button-spinner { animation:none; } }
@media (max-width: 820px) {
  .marketing-nav,.marketing-header-actions>.marketing-button[data-variant="ghost"] { display:none; }
  .marketing-menu-trigger { display:grid; }
  .marketing-header[data-open="true"] { align-items:flex-start; flex-wrap:wrap; }
  .marketing-header[data-open="true"] .marketing-nav { order:3; display:grid; width:100%; gap:4px; padding-top:14px; border-top:1px solid var(--border); }
  .marketing-header[data-open="true"] .marketing-nav a { min-height:44px; display:flex; align-items:center; padding:0 10px; border-radius:10px; }
  .marketing-hero { min-height:0; grid-template-columns:1fr; padding-top:76px; }
  .marketing-hero h1 { font-size:clamp(44px,13vw,66px); }
  .marketing-hero::after { width:168px; height:168px; top:auto; right:-9%; bottom:16%; opacity:.72; }
  .marketing-hero-visual { width:100%; }
  .marketing-orbit-panel { min-height:280px; border-radius:28px 28px 86px 28px; }
  .marketing-section-heading { grid-template-columns:1fr; }
  .marketing-card-grid { grid-template-columns:1fr; }
  .marketing-card[data-variant="feature"]:first-child { grid-column:auto; }
  .marketing-footer-inner { grid-template-columns:1fr 1fr; }
  .marketing-footer-brand { grid-column:1/-1; }
  .marketing-footer-bottom { flex-direction:column; }
}
@media (max-width: 480px) {
  .marketing-header-actions .marketing-button { display:none; }
  .marketing-footer-inner { grid-template-columns:1fr; }
  .marketing-footer-brand { grid-column:auto; }
}
